        c.call('set_debug_view',noise_events=True);c.call('emit_noise',origin={'kind':'position','position':[2,0.8,4]},radius=8)
        token=c.call('bind_control',actor='player')['control'];c.call('talk_npc',actor='player',npc='ally');c.call('interact',actor='player',point='door',action='open')
        path='artifacts/npc-v1.ignis-save';c.call('save_checkpoint',path=path,expected_error=True);c.call('step',ticks=60)
        before=c.call('inspect');old_session=c.call('inspect_dialogue',actor='player')['handle'];assert before['character_controllers']['creature']['airborne'];c.call('save_checkpoint',path=path);saved=(ROOT/path).read_bytes();assert saved[:8]==b'IGNISCPT'
        c.call('capture',path='artifacts/npc-v1-before.png',width=1000,height=700);c.call('step',ticks=10);c.call('load_checkpoint',path=path,mode='recorded');after=c.call('inspect')
        for key in ['runtime_positions','npcs','interactions','presentation','character_controllers']:assert after[key]==before[key],key
        c.call('set_control_input',control=token,input={'x':1,'z':0},expected_error=True);c.call('choose_dialogue',actor='player',session=old_session,choice='yes',expected_error=True);new_session=c.call('inspect_dialogue',actor='player')['handle'];assert new_session!=old_session;c.call('choose_dialogue',actor='player',session=new_session,choice='yes');c.call('step',ticks=240)
        r='artifacts/npc-v1-after-load.replay.json';c.call('save_replay',path=r);assert c.call('run_replay',path=r)['matched'];prefix=c.call('inspect_replay',path=r,tick=0);assert prefix['snapshot']['tick']==60 and prefix['snapshot']['runtime_positions']==before['runtime_positions'];c.call('capture_replay',replay_path=r,path='artifacts/npc-v1-after-load-prefix.png',tick=0,width=1000,height=700);assert (ROOT/'artifacts/npc-v1-before.png').read_bytes()==(ROOT/'artifacts/npc-v1-after-load-prefix.png').read_bytes()
        state=c.call('inspect');pools=state['abilities']['actors']['civil']['resources'];levels={x['id']:x['units'] for x in pools};assert levels['charge']==100 and levels['safe']==1 and levels['bold']==0,levels;assert state['vitality']['actors']['player']['units']>=70
        checks.append('Guard/civil/ally/creature integrate generated routes, cognition/traits, tactical pursuit, support lease, needs/schedule/dialogue, curved hybrid flight and native avatars; live binary checkpoint preserves exact state and replay prefix pixels')
        corrupt=bytearray(saved);corrupt[-1]^=1;(ROOT/'artifacts/npc-v1-corrupt.ignis-save').write_bytes(corrupt);before=c.call('inspect');c.call('load_checkpoint',path='artifacts/npc-v1-corrupt.ignis-save',expected_error=True);assert c.call('inspect')==before
        c.call('load_checkpoint',path=path,mode='continuous');c.call('step',ticks=10);c.call('save_checkpoint',path=path);c.call('load_checkpoint',path=path);execution=c.call('inspect_execution');assert execution['mode']=='continuous' and execution['retained']['ticks']==0
        c.call('reset');c.call('start_multiplayer_host',address='127.0.0.1:0',capacity=1);c.call('pause');before=c.call('inspect_checkpoint');c.call('load_checkpoint',path=path,expected_error=True);assert c.call('inspect_checkpoint')==before;c.call('stop_multiplayer_host')
        checks.append('Bad checksum preserves live world; old ownership/session tokens expire, new session continues, continuous mode saves and restores without log/history/server')
        result={'passed':True,'checks':checks,'native_window':window,'build_id':c.call('inspect')['build_id']};(ROOT/'artifacts/npc-checkpoint-verification.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'passed':True,'checks':len(checks),'build_id':result['build_id']}))
